<script lang="ts">
import {ModelCache} from '../modelCache';
const cache=new ModelCache<import('monaco-editor').editor.ITextModel>(16);
let modelSession=0;
if(typeof window!=='undefined')window.addEventListener('sql-killer-project',()=>{modelSession++;cache.clear()});
</script>
<script setup lang="ts">
import {onMounted,onBeforeUnmount,watch,ref} from 'vue';
import * as monaco from 'monaco-editor/esm/vs/editor/editor.api.js';
import 'monaco-editor/esm/vs/basic-languages/sql/sql.contribution';
import EditorWorker from 'monaco-editor/esm/vs/editor/editor.worker?worker';
import {format} from 'sql-formatter';
import {api,byteOffset,type Analysis,type Schema} from '../api';
import type {SourceRange} from '../generated/SourceRange';
import type {Completion} from '../generated/Completion';
const props=withDefaults(defineProps<{modelValue:string,id:string,schema:Schema,engine?:string,theme?:string,language?:string}>(),{engine:'sqlite',theme:'light',language:'sql'});
const emit=defineEmits<{ 'update:modelValue':[value:string],run:[all:boolean],diagnostics:[analysis:Analysis]}>();
let decorations:monaco.editor.IEditorDecorationsCollection|undefined;let origin={line:1,column:1,version:0,id:''};
const host=ref<HTMLElement>();const choices=ref<Completion[]>([]);const referenceNotice=ref('');let cacheKey='';let pendingReference:{model:monaco.editor.ITextModel,version:number,range:monaco.Selection,schema:Schema,engine:string}|undefined;let editor:monaco.editor.IStandaloneCodeEditor|undefined;let model:monaco.editor.ITextModel|undefined;const disposables:monaco.IDisposable[]=[];let timer:ReturnType<typeof setTimeout>|undefined;let diagnostics:Analysis={diagnostics:[],ast:[],statements:[]};
(self as typeof self & {MonacoEnvironment: monaco.Environment}).MonacoEnvironment={getWorker:()=>new EditorWorker()};
async function analyze(){if(!model||props.language!=='sql')return;const current=model;const version=current.getVersionId();const analyzedSchema=props.schema;const context=`${props.id}:${props.engine}:${props.schema.version}`;try{const r=await api<Analysis>('analyze',{sql:current.getValue(),engine:props.engine,schema:props.schema});if(analyzedSchema!==props.schema||current!==model||current.isDisposed()||current.getVersionId()!==version||context!==`${props.id}:${props.engine}:${props.schema.version}`)return;diagnostics=r;monaco.editor.setModelMarkers(current,'sql-killer',r.diagnostics.map(d=>({message:d.message,severity:d.severity==='error'?monaco.MarkerSeverity.Error:monaco.MarkerSeverity.Warning,startLineNumber:d.range.line,startColumn:d.range.column,endLineNumber:d.range.end_line,endColumn:d.range.end_column,source:d.category})));emit('diagnostics',r);}catch{/* live analysis does not interrupt typing */}}
function createModel(){decorations?.clear();choices.value=[];const old=cacheKey;editor?.setModel(null);if(old)cache.release(old);const uri=monaco.Uri.parse(`inmemory://sql-killer/${modelSession}/${encodeURIComponent(props.id)}.${props.language}`);cacheKey=uri.toString();model=cache.acquire(cacheKey,()=>monaco.editor.createModel(props.modelValue,props.language,uri));if(model.getValue()!==props.modelValue)model.setValue(props.modelValue);editor?.setModel(model);void analyze();}
onMounted(()=>{editor=monaco.editor.create(host.value!,{automaticLayout:true,fontFamily:'Cascadia Code, Consolas, Microsoft YaHei, monospace',fontSize:14,lineHeight:24,minimap:{enabled:false},padding:{top:18,bottom:16},scrollBeyondLastLine:false,roundedSelection:true,wordWrap:'on',tabSize:2,theme:props.theme==='dark'?'vs-dark':'vs',fixedOverflowWidgets:true});createModel();decorations=editor.createDecorationsCollection();
 disposables.push(editor.onDidChangeModelContent(()=>{decorations?.clear();emit('update:modelValue',editor!.getValue());clearTimeout(timer);timer=setTimeout(()=>void analyze(),450);}));
 editor.addCommand(monaco.KeyMod.CtrlCmd|monaco.KeyCode.Enter,()=>emit('run',false));editor.addCommand(monaco.KeyMod.CtrlCmd|monaco.KeyMod.Shift|monaco.KeyCode.Enter,()=>emit('run',true));
 disposables.push(monaco.languages.registerCompletionItemProvider('sql',{triggerCharacters:['.',' '],provideCompletionItems:async(m,p)=>{if(m!==model)return{suggestions:[]};const word=m.getWordUntilPosition(p);const version=m.getVersionId();const completedSchema=props.schema;const context=`${props.engine}:${props.schema.version}`;const list=await api<Completion[]>('complete',{sql:m.getValue(),cursor:byteOffset(m.getValue(),m.getOffsetAt(p)),schema:props.schema});if(completedSchema!==props.schema||m!==model||m.isDisposed()||m.getVersionId()!==version||context!==`${props.engine}:${props.schema.version}`)return{suggestions:[]};const kinds:Record<string,monaco.languages.CompletionItemKind>={column:monaco.languages.CompletionItemKind.Field,table:monaco.languages.CompletionItemKind.Class,function:monaco.languages.CompletionItemKind.Function,keyword:monaco.languages.CompletionItemKind.Keyword,snippet:monaco.languages.CompletionItemKind.Snippet};return{suggestions:list.map(c=>({label:c.label,insertText:c.insert_text,detail:c.detail,kind:kinds[c.kind]??monaco.languages.CompletionItemKind.Text,range:new monaco.Range(p.lineNumber,word.startColumn,p.lineNumber,word.endColumn)}))};}}));
 disposables.push(monaco.languages.registerDocumentFormattingEditProvider('sql',{provideDocumentFormattingEdits:m=>{if(m!==model)return[];try{return[{range:m.getFullModelRange(),text:format(m.getValue(),{language:props.engine==='mysql'?'mysql':'sqlite',keywordCase:'upper'})}]}catch{return[]}}}));
 disposables.push(monaco.languages.registerHoverProvider('sql',{provideHover:(m,p)=>{if(m!==model)return;const word=m.getWordAtPosition(p)?.word;const cols=props.schema.relations.flatMap(r=>r.columns.filter(c=>c.name===word).map(c=>`${r.name}.${c.name} · ${c.data_type} · ${c.primary_key?'主键':c.nullable?'可空':'NOT NULL'}`));if(cols.length)return{contents:cols.map(value=>({value}))};}}));
 disposables.push(monaco.languages.registerCodeActionProvider('sql',{provideCodeActions:(m,range)=>{if(m!==model)return{actions:[],dispose(){}};return{actions:diagnostics.diagnostics.filter(d=>d.replacement&&d.range.line>=range.startLineNumber&&d.range.line<=range.endLineNumber).map(d=>({title:`替换为 ${d.replacement}`,kind:'quickfix',edit:{edits:[{resource:m.uri,versionId:m.getVersionId(),textEdit:{range:new monaco.Range(d.range.line,d.range.column,d.range.end_line,d.range.end_column),text:d.replacement!}}]}})),dispose(){}};}}));
});
watch(()=>[props.id,props.language],createModel);watch(()=>props.engine,()=>void analyze());watch(()=>props.modelValue,v=>{if(model&&model.getValue()!==v)model.setValue(v)});watch(()=>props.schema,()=>void analyze(),{deep:true});watch(()=>props.theme,t=>monaco.editor.setTheme(t==='dark'?'vs-dark':'vs'));
onBeforeUnmount(()=>{clearTimeout(timer);disposables.forEach(d=>d.dispose());editor?.dispose();if(cacheKey)cache.release(cacheKey);});
async function source(all=false):Promise<string>{if(!editor||!model)return props.modelValue;const selection=editor.getSelection();origin={line:1,column:1,version:model.getVersionId(),id:props.id};if(!all&&selection&&!selection.isEmpty()){origin.line=selection.startLineNumber;origin.column=selection.startColumn;return model.getValueInRange(selection);}if(all)return model.getValue();const r=await api<{sql:string,range:SourceRange}|null>('statement',{sql:model.getValue(),cursor:byteOffset(model.getValue(),model.getOffsetAt(editor.getPosition()!))});if(r){origin.line=r.range.line;origin.column=r.range.column;}return r?.sql??model.getValue();}
function highlight(range:SourceRange|null){if(!editor||!model||!range||origin.id!==props.id||origin.version!==model.getVersionId()){decorations?.clear();return;}const line=(n:number)=>origin.line+n-1;const col=(n:number,c:number)=>c+(n===1?origin.column-1:0);decorations?.set([{range:new monaco.Range(line(range.line),col(range.line,range.column),line(range.end_line),col(range.end_line,range.end_column)),options:{className:'sql-motion-highlight',inlineClassName:'sql-motion-text',overviewRuler:{color:'#3b82f6',position:monaco.editor.OverviewRulerLane.Full}}}]);}

function insert(text:string){editor?.executeEdits('insert',[{range:editor.getSelection()!,text,forceMoveMarkers:true}]);editor?.focus();}
async function insertReference(relation:string,column=''){
 if(!model||!editor)return;const current=model,version=current.getVersionId(),schema=props.schema,engine=props.engine;const range=editor.getSelection()!;
 const result=await api<Completion[]>('resolve_reference',{sql:current.getValue(),cursor:byteOffset(current.getValue(),current.getOffsetAt(editor.getPosition()!)),schema:props.schema,engine:props.engine,relation,column});
 if(schema!==props.schema||engine!==props.engine||current!==model||current.isDisposed()||version!==current.getVersionId())return;
 pendingReference={model:current,version,range,schema,engine};referenceNotice.value=result.length?'':'当前查询尚未引用此表，请先将表加入 FROM 或 JOIN。';
 if(result.length===1)choose(result[0].insert_text);else choices.value=result;
}
function choose(text:string){const p=pendingReference;if(p&&p.schema===props.schema&&p.engine===props.engine&&p.model===model&&!p.model.isDisposed()&&p.version===p.model.getVersionId())editor?.executeEdits('schema-reference',[{range:p.range,text,forceMoveMarkers:true}]);choices.value=[];editor?.focus();}
defineExpose({source,insert,insertReference,highlight,format:()=>editor?.getAction('editor.action.formatDocument')?.run(),focus:()=>editor?.focus()});
</script>
<template><div v-if="referenceNotice" role="status" class="notice">{{referenceNotice}}<button @click="referenceNotice=''">关闭</button></div><div v-if="choices.length" class="notice" role="group" aria-label="选择表别名"><span>此表有多个引用，请选择：</span><button v-for="c in choices" :key="c.label" @click="choose(c.insert_text)">{{c.label}}</button></div><div ref="host" class="sql-editor" :data-editor="id" /></template>
